overlay.innerHTML=`<section role="dialog" aria-modal="true" aria-label="META 5" style="width:min(1200px,96vw);max-height:94vh;overflow:auto;background:var(--bg,#18181c);border:1px solid #666;border-radius:14px;padding:22px"><header style="display:flex;justify-content:space-between"><div><small>ЛОКАЛЬНАЯ META 5</small><h2>Агент и проекты</h2></div><button id="x5close" class="outline-btn">Закрыть</button></header><p id="x5health" role="status">Подключение…</p><nav style="display:flex;gap:8px;flex-wrap:wrap;margin:12px 0"><button class="outline-btn" data-m5tab="task">Задача</button><button class="outline-btn" data-m5tab="project">Проект</button><button class="outline-btn" data-m5tab="models">Модели</button><button class="outline-btn" data-m5tab="memory">Память</button></nav><label>Папка внутри D:\\META\\Projects <input class="setting-input" id="x5project" value="."></label><div id="x5task" class="m5tab"><p>Работа идёт в отдельной копии. Применение правок — после просмотра общей заявки.</p><textarea id="x5prompt" class="setting-textarea" style="width:100%;min-height:100px" maxlength="20000" placeholder="Например: прочитай проект, найди ошибку, исправь точной правкой и добавь тест"></textarea><div style="display:flex;gap:12px;flex-wrap:wrap;margin:12px 0"><label>Модель <select id="x5model" class="setting-select"><option value="auto">Автоматически по замерам</option></select></label><label>Шагов <input id="x5steps" class="setting-input" type="number" min="1" max="60" value="24"></label><label>Исполнение <select id="x5backend" class="setting-select"><option value="native">Доверенный код Windows</option><option value="docker">Docker без сети</option></select></label></div><label style="display:block"><input type="checkbox" id="x5create"> Создать папку проекта, если её нет</label><label style="display:block"><input type="checkbox" id="x5runallowed"> Разрешить тесты и локальные серверы этой задачи</label><label style="display:block"><input type="checkbox" id="x5install"> Разрешить скачивание зависимостей в рабочую копию</label><p class="fineprint">Windows-режим выполняет код с правами пользователя и не является защитной песочницей. Если Docker недоступен, изолированный режим выдаст ошибку и не переключится на Windows сам.</p><div style="display:flex;gap:8px;flex-wrap:wrap;margin:12px 0"><button id="x5start" class="action-primary">Запустить</button><button id="x5stop" class="danger-btn" disabled>Остановить</button><button id="x5resume" class="outline-btn" hidden>Продолжить</button><button id="x5history" class="outline-btn">История</button></div><strong id="x5status" role="status">Готов</strong><div id="x5historylist"></div><ol id="x5plan"></ol><pre id="x5progress" style="white-space:pre-wrap;max-height:200px;overflow:auto"></pre><p id="x5result" style="white-space:pre-wrap"></p><div id="x5sources"></div><div id="x5artifacts"></div><pre id="x5diff" style="white-space:pre-wrap;max-height:400px;overflow:auto"></pre><div id="x5approval"></div><details><summary>Технический журнал</summary><pre id="x5log" style="white-space:pre-wrap;max-height:260px;overflow:auto"></pre></details></div><div id="x5projecttab" class="m5tab" hidden><div style="display:flex;gap:8px;margin:15px 0"><button id="x5index" class="outline-btn">Обновить карту проекта</button><input id="x5query" class="setting-input" placeholder="Текст или имя функции"><button id="x5search" class="outline-btn">Найти</button></div><div id="x5map"></div><label>Строки <input id="x5line" type="number" min="1" value="1" style="width:80px"><button id="x5readmore" class="outline-btn">Читать диапазон</button></label><pre id="x5file" style="white-space:pre-wrap;max-height:460px;overflow:auto"></pre><div id="x5matches"></div></div><div id="x5models" class="m5tab" hidden><p>Профили выбираются по коротким проверкам на этом компьютере. Это не измерение общего интеллекта модели.</p><div id="x5profileform"></div><button id="x5saveprofiles" class="action-primary">Сохранить выбор</button><button id="x5benchmark" class="outline-btn">Измерить установленные модели</button><div id="x5bench" style="max-height:420px;overflow:auto;margin-top:16px"></div></div><div id="x5memory" class="m5tab" hidden><label><input id="x5capture" type="checkbox"> Запоминать явно сообщённые предпочтения</label><p class="fineprint">Секреты не сохраняются. Старые воспоминания прежней версии остаются в прежнем разделе настроек.</p><textarea id="x5fact" class="setting-textarea" style="width:100%" maxlength="600" placeholder="Факт или предпочтение"></textarea><button id="x5addfact" class="action-primary">Добавить</button><div id="x5facts"></div></div></section>`;
document.body.append(overlay);const el=name=>get('x5'+name);
let task=localStorage.getItem('meta5-last-task'),polling=false,selectedFile=null,proposal=null,activeTask=false,modelsList=[],benchTimer=null;
