const states={queued:'В очереди',running:'Работает',pending:'Ожидает подтверждения',completed:'Завершено',paused:'Пауза — прогресс сохранён',interrupted:'Прервано перезапуском',cancelled:'Остановлено',failed:'Ошибка',step_limit:'Лимит шагов',time_limit:'Лимит времени'};
