function sources(container,items){container.replaceChildren();for(const s of items||[]){const row=make('p');const a=make('a',s.title||s.url);a.href=s.url;a.target='_blank';a.rel='noopener noreferrer';row.append(a,make('small',s.opened?' · страница прочитана':' · поисковая выдержка'));container.append(row);}}
function tab(name){for(const [key,id] of [['task','task'],['project','projecttab'],['models','models'],['memory','memory']])el(id).hidden=key!==name;if(name==='models')loadModels();if(name==='memory')loadMemory();}
