el('close').onclick=()=>overlay.hidden=true;overlay.onclick=e=>{if(e.target===overlay)overlay.hidden=true;};
open.onclick=async()=>{overlay.hidden=false;try{const s=await call('/status');el('health').textContent='Core '+s.version+' · '+(s.capabilities.docker?'Docker найден':'Docker не установлен')+' · '+(s.capabilities.pytest?'pytest доступен':'pytest отсутствует');if(s.active)task=s.active;await loadModelOptions();if(task)await refresh();}catch(e){el('health').textContent=e.message;}};
